### 2.5  Repository Layer

```java
// src/main/java/com/example/bookapi/repository/BookRepository.java
package com.example.bookapi.repository;

import com.example.bookapi.model.Book;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

@Repository
public interface BookRepository extends JpaRepository<Book, Long> {}
```

---

### 2.6  Service Layer

```java
// src/main/java/com/example/bookapi/service/BookService.java
package com.example.bookapi.service;

import com.example.bookapi.model.Book;
import com.example.bookapi.repository.BookRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional
public class BookService {

    private final BookRepository repo;

    public BookService(BookRepository repo) {
        this.repo = repo;
    }

    public List<Book> listAll() { return repo.findAll(); }

    public Book getById(Long id) {
        return repo.findById(id)
                   .orElseThrow(() -> new BookNotFoundException(id));
    }

    public Book create(Book book) { return repo.save(book); }

    public Book update(Long id, Book updated) {
        return repo.findById(id)
                   .map(existing -> {
                       existing.setTitle(updated.getTitle());
                       existing.setAuthor(updated.getAuthor());
                       existing.setYear(updated.getYear());
                       return repo.save(existing);
                   })
                   .orElseThrow(() -> new BookNotFoundException(id));
    }

    public void delete(Long id) {
        if (!repo.existsById(id)) {
            throw new BookNotFoundException(id);
        }
        repo.deleteById(id);
    }
}
```

