### 2.8  Global Exception Handler

```java
// src/main/java/com/example/bookapi/controller/GlobalExceptionHandler.java
package com.example.bookapi.controller;

import com.example.bookapi.model.BookNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(BookNotFoundException.class)
    public ResponseEntity<String> handleNotFound(BookNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ex.getMessage());
    }

    // Add more handlers (e.g., for Validation) as needed
}
```

